package com.mindbridge.safety.review;  import com.mindbridge.common.service.CurrentUserService; import com.mindbridge.safety.event.SafetyEventStatus; import com.mindbridge.safety.event.exception.SafetyEventInputException; import com.mindbridge.safety.review.dto.ExpertReviewResponse; import com.mindbridge.safety.review.dto.SafetyEventDetailResponse; import com.mindbridge.safety.review.dto.SafetyEventSummaryResponse; import com.mindbridge.safety.review.dto.SubmitReviewRequest; import jakarta.validation.Valid; import org.springframework.data.domain.Page; import org.springframework.data.domain.Pageable; import org.springframework.data.web.PageableDefault; import org.springframework.http.HttpStatus; import org.springframework.http.ResponseEntity; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.ExceptionHandler; import org.springframework.web.bind.annotation.GetMapping; import org.springframework.web.bind.annotation.PathVariable; import org.springframework.web.bind.annotation.PostMapping; import org.springframework.web.bind.annotation.RequestBody; import org.springframework.web.bind.annotation.RequestMapping; import org.springframework.web.bind.annotation.RequestParam; import org.springframework.web.bind.annotation.RestController;  import java.util.UUID;  @RestController @RequestMapping("/expert-reviews") @PreAuthorize("hasAnyRole('EXPERT', 'ADMIN')") public class ExpertReviewController {      private final ExpertReviewService expertReviewService;     private final CurrentUserService currentUserService;      public ExpertReviewController(ExpertReviewService expertReviewService,                                   CurrentUserService currentUserService) {         this.expertReviewService = expertReviewService;         this.currentUserService = currentUserService;     }      @GetMapping("/events")     public ResponseEntity<Page<SafetyEventSummaryResponse>> listEvents(             @RequestParam(required = false) SafetyEventStatus status,             @RequestParam(required = false) Integer riskLevel,             @PageableDefault(size = 20, sort = "createdAt") Pageable pageable) {          Short shortRiskLevel = riskLevel != null ? riskLevel.shortValue() : null;         Page<SafetyEventSummaryResponse> events =                 expertReviewService.listEvents(status, shortRiskLevel, pageable);         return ResponseEntity.ok(events);     }      @GetMapping("/events/{eventId}")     public ResponseEntity<SafetyEventDetailResponse> getEventDetail(@PathVariable UUID eventId) {         SafetyEventDetailResponse detail =                 expertReviewService.getEventDetailAndRecordOpened(eventId);         return ResponseEntity.ok(detail);     }      @PostMapping("/events/{eventId}/review")     public ResponseEntity<ExpertReviewResponse> submitReview(             @PathVariable UUID eventId,             @Valid @RequestBody SubmitReviewRequest request) {          UUID reviewerId = currentUserService.getCurrentUserId();         ExpertReviewResponse response =                 expertReviewService.submitReview(eventId, reviewerId, request);         return ResponseEntity.status(HttpStatus.CREATED).body(response);     }      @ExceptionHandler(org.springframework.dao.DataIntegrityViolationException.class)     public ResponseEntity<ErrorResponse> handleDuplicateReview(             org.springframework.dao.DataIntegrityViolationException ex) {         return ResponseEntity.status(HttpStatus.CONFLICT)                 .body(new ErrorResponse("DUPLICATE_REVIEW", "You have already reviewed this event"));     }      @ExceptionHandler(SafetyEventInputException.class)     public ResponseEntity<ErrorResponse> handleSafetyEventError(SafetyEventInputException ex) {         if (ex.getMessage() != null && ex.getMessage().contains("not found")) {             return ResponseEntity.status(HttpStatus.NOT_FOUND)                     .body(new ErrorResponse("EVENT_NOT_FOUND", ex.getMessage()));         }         return ResponseEntity.status(HttpStatus.BAD_REQUEST)                 .body(new ErrorResponse("VALIDATION_ERROR", ex.getMessage()));     }      public record ErrorResponse(String code, String message) {} }